scripts:
const tabContainers = document.querySelectorAll('.cb-post-tabs');

tabContainers.forEach(container => {
  const btns = container.querySelectorAll('.cb-post-tabs__btn');
  const panels = container.querySelectorAll('.cb-post-tabs__panel');

  btns.forEach(btn => {
    btn.addEventListener('click', () => {
      // Знімаємо active з усіх кнопок та панелей у поточному компоненті
      btns.forEach(b => b.classList.remove('active'));
      panels.forEach(p => p.classList.remove('active'));

      // Додаємо active до клікнутої кнопки
      btn.classList.add('active');

      // Знаходимо відповідну панель та показуємо її
      const targetId = btn.getAttribute('data-target');
      const targetPanel = container.querySelector('#' + targetId);
      if (targetPanel) {
        targetPanel.classList.add('active');
      }
    });
  });
});

styles:
.cb-post-tabs {
  display: flex;
  flex-direction: column;
  gap: 20px;
  font-family: inherit;
}

.cb-post-tabs__nav {
  display: flex;
  gap: 12px;
  border-bottom: 2px solid #e5e5e5;
}

.cb-post-tabs__btn {
  padding: 12px 24px;
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  cursor: pointer;
  font-size: 16px;
  font-weight: 600;
  color: #717171;
  transition: all 0.3s ease;
}

.cb-post-tabs__btn:hover {
  color: #222;
}

.cb-post-tabs__btn.active {
  color: #4caf4f;
  border-bottom-color: #4caf4f;
}

.cb-post-tabs__panel {
  display: none;
  padding: 24px;
  background: #fff;
  border-radius: 12px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.08);
}

.cb-post-tabs__panel.active {
  display: block;
  animation: fadeIn 0.4s;
}

.cb-post-tabs__panel img {
  max-width: 100%;
  height: auto;
  border-radius: 8px;
  display: block;
}

.cb-post-tabs__title {
  margin: 0;
  font-size: 24px;
}

.cb-post-tabs__text {
  font-size: 16px;
  line-height: 1.6;
  color: #444;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}
